// Pseudocode sketch of propagation loop using given semantics
function propagate(constraints, domains) {
  while (changes) {
    changes = false;
    for (const constraint of constraints) {
      for (const assignment of domains) {
        const result = evaluate(constraint, assignment);
        if (result === 'F') {
          domains = prune(domains, assignment);
          changes = true;
        }
      }
    }
  }
  return domains;
}
```

## Why This Is Asked

To evaluate ability to design minimal-witness solvers for Horn-like rules and detect derivability with backtracking.

## Key Concepts

- Horn clauses
- Minimal witness extraction
- Forward-chaining with backtracking
- Cycle detection in derivations

## Code Example

```javascript
// simple forward-chaining for (A∧B)→C rules
function canDerive(target, base, rules){
  const derived = new Set(base);
  let changed = true;
  while (changed) {
    changed = false;
    for (const [A,B,C] of rules){
      if (derived.has(A) && derived.has(B) && !derived.has(C)){
        derived.add(C);
        changed = true;
      }
    }
  }
  return derived.has(target);
}
```

